    ring(0,0,1,p.primary);for(let i=0;i<4;i++){const a=i*Math.PI/2;path([[Math.cos(a)*.7,Math.sin(a)*.7],[Math.cos(a)*.94,Math.sin(a)*.94]],p.secondary,.1);}
