      for(let i=1;i<6;i++){const x=length*i/6;c.strokeStyle=i===Math.floor(time*6)%6?p.trim:p.secondary;c.beginPath();c.arc(x,0,7,-Math.PI*.7,Math.PI*.7);c.moveTo(x,0);c.lineTo(x+4,-4);c.stroke();}
