    for(let i=0;i<12;i++)ray(i*Math.PI/6,r*.76,r*(i%2?1.12:1.35),i%2?p.primary:p.secondary,2.5);
    c.fillStyle=p.trim;c.globalAlpha=fade*fade;c.beginPath();c.arc(0,0,r*.32,0,Math.PI*2);c.fill();
