        ctx.shadowBlur = enemy.flash > 0 ? 16 : enemy.isBoss ? 10 : userSettings.quality === "high" ? 8 : 0;
        ctx.shadowColor = enemy.flash > 0 ? "#ffffff" : enemy.strokeColor;
        ctx.fillStyle = enemy.flash > 0 ? "#ffffff" : enemy.color;
        ctx.strokeStyle = enemy.flash > 0 ? "#ffffff" : enemy.strokeColor;
